import functools
from typing import ForwardRef, List
from fastapi import FastAPI, Depends
from fastapi.dependencies.utils import get_typed_signature
import pytest

# Define a class to use for forward reference
class MyModel:
    pass

def wrapper(func):
    @functools.wraps(func)
    def wrapped(*args, **kwargs):
        return func(*args, **kwargs)
    return wrapped

def test_wrapped_method_type_inference():
    # This function uses a forward reference to MyModel
    def my_endpoint(item: "MyModel"):
        return {"item": item}

    wrapped_endpoint = wrapper(my_endpoint)

    # This should not raise NameError
    try:
        sig = get_typed_signature(wrapped_endpoint)
        # Check if the annotation was resolved to MyModel
        param = list(sig.parameters.values())[0]
        assert param.annotation is MyModel
    except NameError as e:
        pytest.fail(f"NameError raised: {e}")

if __name__ == "__main__":
    test_wrapped_method_type_inference()
    print("Test passed!")
